describe('Dashboard Sidebar to Bottom Nav Bar on Mobile', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should transform sidebar to bottom nav bar on mobile viewport', () => {
    // Set viewport to mobile size
    cy.viewport('iphone-x');

    // Verify sidebar is visible and in standard desktop position
    cy.get('[data-testid="sidebar-menu"]').should('be.visible');
    cy.get('[data-testid="sidebar-menu"]').should('have.class', 'sidebar-desktop');

    // Verify bottom nav bar is not visible yet
    cy.get('[data-testid="bottom-nav-bar"]').should('not.exist');

    // Resize viewport to trigger mobile layout
    cy.viewport('iphone-12');

    // Verify sidebar is hidden or transformed
    cy.get('[data-testid="sidebar-menu"]').should('not.exist');

    // Verify bottom nav bar appears
    cy.get('[data-testid="bottom-nav-bar"]').should('be.visible');
    cy.get('[data-testid="bottom-nav-bar"]').should('have.class', 'bottom-nav-mobile');

    // Verify bottom nav bar contains expected links
    cy.get('[data-testid="bottom-nav-item-dashboard"]').should('be.visible');
    cy.get('[data-testid="bottom-nav-item-settings"]').should('be.visible');
    cy.get('[data-testid="bottom-nav-item-profile"]').should('be.visible');

    // Verify bottom nav bar is fixed at the bottom
    cy.get('[data-testid="bottom-nav-bar"]').should('have.css', 'bottom: 0px');
    cy.get('[data-testid="bottom-nav-bar"]').should('have.css', 'left: 0px');
  });

  it('should handle sidebar to bottom nav transformation with active state and edge cases', () => {
    // Set viewport to mobile size
    cy.viewport('iphone-12');

    // Verify bottom nav bar is visible
    cy.get('[data-testid="bottom-nav-bar"]').should('be.visible');

    // Verify active link is highlighted
    cy.get('[data-testid="bottom-nav-item-dashboard"]').should('have.class', 'active');
    cy.get('[data-testid="bottom-nav-item-settings"]').should('not.have.class', 'active');

    // Click on another navigation item
    cy.get('[data-testid="bottom-nav-item-settings"]').click();

    // Verify active state changes
    cy.get('[data-testid="bottom-nav-item-settings"]').should('have.class', 'active');
    cy.get('[data-testid="bottom-nav-item-dashboard"]').should('not.have.class', 'active');

    // Verify bottom nav bar remains fixed
    cy.get('[data-testid="bottom-nav-bar"]').should('be.visible');
    cy.get('[data-testid="bottom-nav-bar"]').should('have.css', 'bottom: 0px');

    // Test edge case: empty state on mobile
    cy.get('[data-testid="bottom-nav-item-profile"]').click();
    cy.get('[data-testid="profile-page-content"]').should('be.visible');
    cy.get('[data-testid="profile-page-content"]').should('contain', 'User Profile');

    // Verify bottom nav bar is still present after navigation
    cy.get('[data-testid="bottom-nav-bar"]').should('be.visible');
  });
});
